import { useState, useEffect } from 'react';
import { motion } from 'motion/react';
import { Shield } from 'lucide-react';

// Paste your custom base64 image string here (e.g. "data:image/png;base64,...")
export const CUSTOM_LOGO_BASE64 = "data:image/png;base64,";

const CHARS = '!<>-_\\/[]{}—=+*^?#________';

export function ScrambleText({ text, className = "" }: { text: string; className?: string }) {
  const [displayText, setDisplayText] = useState('');

  useEffect(() => {
    let iteration = 0;
    
    // Fill initial with random characters
    const initial = text.split('').map(c => c === ' ' ? ' ' : CHARS[Math.floor(Math.random() * CHARS.length)]).join('');
    setDisplayText(initial);

    const intervalId = setInterval(() => {
      setDisplayText((current) =>
        text
          .split('')
          .map((letter, index) => {
            if (index < iteration) {
              return text[index];
            }
            return letter === ' ' ? ' ' : CHARS[Math.floor(Math.random() * CHARS.length)];
          })
          .join('')
      );

      if (iteration >= text.length) {
        clearInterval(intervalId);
      }

      iteration += 1 / 3;
    }, 40);

    return () => clearInterval(intervalId);
  }, [text]);

  return <span className={className}>{displayText}</span>;
}

interface WelcomeScreenProps {
  onComplete: () => void;
}

export function WelcomeScreen({ onComplete }: WelcomeScreenProps) {
  useEffect(() => {
    const timer = setTimeout(onComplete, 4500); // Wait 4.5s then trigger fade out
    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <motion.div
      initial={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ duration: 0.5, ease: 'easeOut' }}
      className="fixed inset-0 z-[100] bg-bg-base flex flex-col items-center justify-center selection:bg-accent-muted"
    >
      <motion.div
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 0.8, ease: 'easeOut' }}
        className="flex flex-col items-center"
      >
        <div className="w-24 h-24 bg-bg-surface border border-border-default rounded-full flex items-center justify-center mb-8 relative drop-shadow-xl overflow-hidden">
            <div className="absolute inset-0 rounded-full border border-border-active/30 animate-[spin_4s_linear_infinite]" />
            <div className="absolute inset-2 rounded-full border border-border-default animate-[spin_3s_linear_infinite_reverse]" />
            {CUSTOM_LOGO_BASE64 ? (
              <img src={CUSTOM_LOGO_BASE64} alt="Custom Logo" className="w-12 h-12 relative z-10 object-contain" />
            ) : (
              <Shield className="w-10 h-10 text-accent relative z-10" />
            )}
        </div>
        
        <h1 className="text-4xl md:text-5xl font-bold tracking-[0.2em] text-text-primary uppercase mb-6">
          <ScrambleText text="arkenSTONE" />
        </h1>
        
        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1, duration: 1 }}
          className="flex flex-col items-center gap-3"
        >
          <div className="h-[1px] w-32 bg-gradient-to-r from-transparent via-border-active to-transparent mb-2" />
          <p className="text-xs md:text-sm tracking-[0.4em] text-accent font-semibold flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-accent animate-pulse shadow-[0_0_8px_currentColor]" />
            <ScrambleText text="SYSTEM INITIALIZING" className="font-mono" />
          </p>
        </motion.div>
      </motion.div>
    </motion.div>
  );
}
